import random
import logging
from sc2 import maps, run_game, Race, Difficulty
from sc2.player import Bot, Computer
from sc2.bot_ai import BotAI
from sc2.ids.unit_typeid import UnitTypeId
from sc2.ids.ability_id import AbilityId
from sc2.ids.upgrade_id import UpgradeId
from sc2.position import Point2

logging.basicConfig(level=logging.INFO)

class ZergRushBot(BotAI):
    async def on_start(self):
        await self.client.game_step(2)
        self.rushed = False
        self.chat_sent = False
        logging.info("Game started: Zerg Rush Bot initialized.")

    async def on_step(self, iteration):
        # Send a chat message once
        if not self.chat_sent:
            await self.chat_send("GL HF! Prepare for the Zerg rush!")
            self.chat_sent = True

        await self.inject_larva()
        await self.manage_resources()
        await self.research_upgrades()
        await self.train_units()
        await self.build_structures()
        await self.attack_enemy()
        await self.draw_creep_pixelmap()

    async def on_end(self, result):
        logging.info(f"Game ended with result: {result}")

    async def inject_larva(self):
        for queen in self.units(UnitTypeId.QUEEN).idle:
            hatcheries = self.townhalls.ready
            if hatcheries:
                hatch = hatcheries.closest_to(queen)
                if queen.energy >= 25 and not hatch.has_buff(AbilityId.EFFECT_INJECTLARVA):
                    queen(AbilityId.EFFECT_INJECTLARVA, hatch)

    async def manage_resources(self):
        # Build Extractors if we have spawning pool and less than 2 extractors
        if self.structures(UnitTypeId.SPAWNINGPOOL).ready and self.gas_buildings.amount < 2:
            for hatch in self.townhalls.ready:
                vgs = self.vespene_geyser.closer_than(10, hatch)
                for vg in vgs:
                    if not self.gas_buildings.closer_than(1, vg).exists:
                        if self.can_afford(UnitTypeId.EXTRACTOR):
                            drone = self.workers.closest_to(vg)
                            drone.build(UnitTypeId.EXTRACTOR, vg)
                            return

        # Keep workers on minerals and gas
        for hatch in self.townhalls.ready:
            self.distribute_workers()

    async def research_upgrades(self):
        # Research Zergling Speed
        if self.structures(UnitTypeId.SPAWNINGPOOL).ready:
            pool = self.structures(UnitTypeId.SPAWNINGPOOL).ready.first
            if self.can_afford(UpgradeId.ZERGLINGMOVEMENTSPEED) and not self.already_pending_upgrade(UpgradeId.ZERGLINGMOVEMENTSPEED):
                if pool.is_idle:
                    pool.research(UpgradeId.ZERGLINGMOVEMENTSPEED)

    async def train_units(self):
        # Train Zerglings
        for hatch in self.townhalls.ready.idle:
            if self.can_afford(UnitTypeId.ZERGLING) and self.supply_left > 0:
                hatch.train(UnitTypeId.ZERGLING)

        # Train Overlords if supply is low
        if self.supply_left < 2 and self.can_afford(UnitTypeId.OVERLORD):
            for hatch in self.townhalls.ready.idle:
                hatch.train(UnitTypeId.OVERLORD)

        # Train Queens for larva inject
        if self.structures(UnitTypeId.SPAWNINGPOOL).ready and self.units(UnitTypeId.QUEEN).amount < self.townhalls.ready.amount:
            for hatch in self.townhalls.ready.idle:
                if self.can_afford(UnitTypeId.QUEEN):
                    hatch.train(UnitTypeId.QUEEN)

    async def build_structures(self):
        # Build Spawning Pool if not exists
        if not self.structures(UnitTypeId.SPAWNINGPOOL):
            if self.can_afford(UnitTypeId.SPAWNINGPOOL):
                pos = await self.get_build_location(UnitTypeId.SPAWNINGPOOL)
                if pos:
                    drone = self.workers.random
                    drone.build(UnitTypeId.SPAWNINGPOOL, pos)
                    return

        # Build more Hatcheries if minerals allow and less than 2
        if self.townhalls.amount < 2 and self.can_afford(UnitTypeId.HATCHERY):
            pos = await self.get_next_expansion()
            if pos:
                drone = self.workers.closest_to(pos)
                drone.build(UnitTypeId.HATCHERY, pos)
                return

    async def attack_enemy(self):
        # Attack enemy structures with all Zerglings if we have at least 16
        if self.units(UnitTypeId.ZERGLING).amount >= 16 or self.rushed:
            self.rushed = True
            zerglings = self.units(UnitTypeId.ZERGLING).idle
            if zerglings:
                targets = self.enemy_structures
                if targets:
                    target = targets.random.position
                else:
                    target = self.enemy_start_locations[0]
                for zergling in zerglings:
                    zergling.attack(target)

    async def draw_creep_pixelmap(self):
        # Draw creep as purple pixels for debugging
        for y in range(self.game_info.map_size[1]):
            for x in range(self.game_info.map_size[0]):
                pos = Point2((x, y))
                if self.state.creep_cover_map.is_set(pos):
                    await self._client.debug_text_world("•", pos, color=(128, 0, 128), size=8)

    async def get_build_location(self, building_type):
        # Find a buildable location near the main hatchery
        hatch = self.townhalls.ready.first
        pos = hatch.position.towards(self.game_info.map_center, random.randint(5, 8))
        return await self.find_placement(building_type, pos, placement_step=1)

if __name__ == "__main__":
    run_game(
        maps.get("AcropolisLE"),
        [
            Bot(Race.Zerg, ZergRushBot()),
            Computer(Race.Terran, Difficulty.Medium)
        ],
        realtime=False,
        save_replay_as="zerg_rush_bot.SC2Replay"
    )
